using BepInEx.Configuration;
using BrudvikWhiteHilt.Patches.Foraging;
using BrudvikWhiteHilt.Progression;
using Jotunn.Configs;
using Jotunn.Entities;
using Jotunn.Managers;
using UnityEngine;

namespace BrudvikWhiteHilt.Items.Foraging.TinderFungus;

/// <summary>
/// Tinder fungus, hoof-shaped brackets on the burnt stumps of the Ashlands, which the Vikings carried to catch a spark.
/// It burns long in a wood fire and the charcoal kiln turns it into coal. Model: generated by
/// AssetSource/Tools/make_forage_models.py.
/// </summary>
public class TinderFungus : ForageableBase
{
    /// <summary>
    /// Prefab name of the tinder fungus item.
    /// </summary>
    public const string PrefabName = "WhiteHiltTinderFungus";

    private static ConfigEntry<float> fuelValue;

    /// <summary>
    /// Creates the definition. The plugin does this for every such class by reflection when it starts; the game sees
    /// the result only once Add has run. Binds the fuel setting.
    /// </summary>
    public TinderFungus()
    {
        fuelValue = WhiteHiltConfig.BindAdminOnly("Foraging.TinderFungus", "FuelValue", 3f,
            "How much wood one tinder fungus is worth in a wood fire (campfire, hearth, bonfire). Use it from the hotbar on the fire.",
            new AcceptableValueRange<float>(0.5f, 10f));
    }

    /// <summary>
    /// How much wood one tinder fungus is worth in a fire.
    /// </summary>
    public static float FuelValue => fuelValue?.Value ?? 3f;

    /// <inheritdoc/>
    public override string BaseName => PrefabName;

    /// <inheritdoc/>
    protected override string FullName => "Tinder Fungus";

    /// <inheritdoc/>
    protected override string Description => "A hard grey bracket cut from a burnt stump. It catches a spark at once and smoulders for hours in a fire, and the kiln makes coal of it.";

    /// <inheritdoc/>
    protected override string CopyItemFrom => "Coal";

    /// <inheritdoc/>
    protected override string CopyPickableFrom => "Pickable_Mushroom";

    /// <inheritdoc/>
    protected override VegetationConfig Vegetation => new()
    {
        Biome = Heightmap.Biome.AshLands,
        // Groups per zone where the ground suits it; the generator keeps trying spots until they are placed.
        Min = 1,
        Max = 1,
        ForcePlacement = true,
        GroupSizeMin = 1,
        GroupSizeMax = 2,
        GroupRadius = 4f,
        MinAltitude = 1f,
        MaxTilt = 20f,
        ScaleMin = 0.9f,
        ScaleMax = 1.2f,
        BlockCheck = true
    };

    /// <inheritdoc/>
    public override bool Enabled => true;

    /// <inheritdoc/>
    protected override string ExtraDropFrom => null;

    /// <inheritdoc/>
    protected override void ApplyVisual(GameObject visualRoot)
    {
        ReplacePlantMesh(visualRoot, IsItem(visualRoot) ? "tinderfungusitem" : "tinderfungus", 0.65f);
    }

    /// <inheritdoc/>
    protected override void OnAdded()
    {
        ForageFuelPatch.Register(Helpers.Translations.Token(Helpers.Translations.ItemKey(PrefabName)), () => FuelValue);
        ItemManager.Instance.AddItemConversion(new CustomItemConversion(new SmelterConversionConfig
        {
            Station = Smelters.CharcoalKiln,
            FromItem = PrefabName,
            ToItem = "Coal"
        }));
    }
}
